SELECT c.id, u.id, 'french-b1-voyages-et-interculturalite-grammar', 'grammar', 'Les connecteurs d’opposition : tandis que, alors que', 'Comparer deux idées opposées avec des connecteurs.', 54, 25, 'free', 12, true, NULL, '« Tandis que » et « alors que » servent à opposer deux idées dans une même phrase : « En France, on dîne vers vingt heures, tandis qu’à Saint-Domingue, on dîne souvent plus tard. » Ils sont suivis d’un sujet et d’un verbe conjugué, comme « parce que ».', '["..., tandis que...","..., alors que...","Contrairement à...","Par contre..."]'::jsonb
FROM public.courses c
JOIN public.languages l ON l.id = c.language_id
JOIN public.levels lv ON lv.id = c.level_id
JOIN public.course_units u ON u.course_id = c.id AND u.slug = 'voyages-et-interculturalite'
WHERE l.code = 'french' AND lv.code = 'B1'
ON CONFLICT (slug) DO UPDATE SET
  unit_id = EXCLUDED.unit_id, skill = EXCLUDED.skill, title = EXCLUDED.title, description = EXCLUDED.description,
  order_index = EXCLUDED.order_index, xp_reward = EXCLUDED.xp_reward, access_tier = EXCLUDED.access_tier,
