INSERT INTO public.lesson_sections (lesson_id, type, order_index, speaker, line, translation)
VALUES ((SELECT id FROM public.course_lessons WHERE slug = 'french-a2-la-vie-quotidienne-writing'), 'dialogue_line', 0, 'Modèle', 'D’habitude, je me réveille à sept heures. Le lundi et le mercredi, j’ai cours jusqu’à dix-sept heures. Je fais souvent mes devoirs le soir, mais je ne travaille jamais après vingt-deux heures.', 'Normalmente me despierto a las siete. Los lunes y miércoles tengo clases hasta las cinco. A menudo hago mis deberes por la noche, pero nunca trabajo después de las diez.');
