INSERT INTO public.lesson_sections (lesson_id, type, order_index, speaker, line, translation)
VALUES ((SELECT id FROM public.course_lessons WHERE slug = 'french-b1-projets-et-avenir-writing'), 'dialogue_line', 0, 'Modèle', 'Cher Karim, je t’écris pour t’annoncer que j’ai décidé de rentrer à Saint-Domingue à la fin de l’année. C’était une décision difficile, mais ma famille me manque beaucoup. Si tout se passe bien, je reviendrai étudier en France après le lycée. Je n’oublierai jamais cette année incroyable avec vous.', 'Querido Karim, te escribo para anunciarte que decidí regresar a Santo Domingo al final del año. Fue una decisión difícil, pero extraño mucho a mi familia. Si todo va bien, volveré a estudiar en Francia después del bachillerato. Nunca olvidaré este año increíble con ustedes.');
