INSERT INTO public.lesson_sections (lesson_id, type, order_index, speaker, line, translation)
VALUES ((SELECT id FROM public.course_lessons WHERE slug = 'french-b1-sante-et-mode-de-vie-dialogue'), 'dialogue_line', 0, 'Léa', 'Tu sembles beaucoup plus détendue cette semaine !', '¡Pareces mucho más relajada esta semana!');
INSERT INTO public.lesson_sections (lesson_id, type, order_index, speaker, line, translation)
